        return image_patch

    next_to = []
    for cup in cups:
        for plate in plates:
            if abs(cup.horizontal_center - plate.horizontal_center) < min(cup.width, plate.width) / 2:
                next_to.append(cup)
                break

    return next_to[0] if next_to else cups[0]

